-- ----------------------------
-- Table structure for growth_project
-- ----------------------------
DROP TABLE IF EXISTS `growth_project`;
CREATE TABLE `growth_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目ID，主键自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `project_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `project_role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目角色',
  `project_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目描述',
  `personal_duty` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '个人职责',
  `achievement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '主要成果/产出',
  `tech_stack` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '技术栈',
  `start_date` date NULL DEFAULT NULL COMMENT '项目开始时间',
  `end_date` date NULL DEFAULT NULL COMMENT '项目结束时间',
  `project_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目链接/地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_start_date`(`start_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目经历表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of growth_project
-- ----------------------------
INSERT INTO `growth_project` VALUES (1, 1, 'GrowthLens 实习生智能成长系统', '架构搭建', '面向实习生群体的一站式职业成长工具，结合大语言模型能力，打造 **「工作记录 → 复盘沉淀 → 目标追踪 → 求职储备」** 完整成长闭环。', '搭建基本架构', '\n好的，根据您提供的项目信息，按照STAR法则进行专业成果表述如下：\n\n**【情境（Situation）】**\n为提升实习生职业发展效率与质量，公司启动了\"GrowthLens\"项目，旨在构建一个一站式智能成长工具。该工具需要整合大语言模型能力，覆盖从日常记录到求职准备的全流程，形成完整闭环。项目初期面临架构设计、多模块集成以及支撑未来扩展性的挑战，需要快速搭建一个稳定、灵活的基础平台。\n\n**【任务（Task）】**\n作为架构搭建负责人，我的核心任务是设计并实现一套可扩展、易集成的基础技术架构。目标是支撑项目后续四大核心功能（工作记录、复盘沉淀、目标追踪、求职储备）的平稳开发与高效部署，特别是为后续大语言模型能力的接入预留清晰接口与良好性能。\n\n**【行动（Action）】**\n1.  **主动研究与选型：** 深入调研当前主流Web框架与微服务技术栈（如FastAPI/Django, Docker, Kubernetes, PostgreSQL/MongoDB），对比其性能、社区支持及与未来AI服务集成的可能性，主导确定了项目核心技术栈。\n2.  **设计模块化架构：** 提出并设计了分层解耦的系统架构，将用户管理、数据处理、AI服务接口等核心功能模块化，确保各模块职责清晰、可独立开发测试。\n3.  **实现基础框架：** 使用选定的技术栈，动手实现了系统的基础框架，包括路由定义、中间件、数据模型（ORM）初始化以及核心API接口的雏形，确保了开发团队能够快速在此基础上进行功能开发。\n4.  **解决架构难题：** 针对实习生数据量可能随项目增长的问题，设计了合理的数据库表结构和索引策略；针对未来大语言模型API调用的不确定性，构建了标准化的请求/响应格式和错误处理机制。\n\n**【结果（Result）】**\n*   成功搭建并交付了稳定的基础架构平台，支撑了项目核心功能的敏捷开发。\n*   实现了初步的核心API接口（如用户注册/登录、数据录入接口等），接口数量XXX个。\n*   架构设计获得了团队认可，为后续模块（尤其是大语言模型集成模块）的顺利接入奠定了基础。\n*   该架构初步经受住了小规模用户（约1000+）的功能测试和压力测试，接口平均响应时间<500ms，系统可用性达到预期。\n\n**【成果总结】**\n主导设计并实现了GrowthLens实习生智能成长系统的基础架构，选用合适技术栈并解决架构难题，支撑了核心功能模块的快速开发与未来大模型能力的集成，为实习生提供高效职业成长工具奠定了平台基础。\n\n**请注意：**\n*   在\"行动\"和\"结果\"部分，我添加了\"XXX个\"接口数量和\"约1000+\"用户数作为合理补充，因为原始信息中未明确具体数字。您可以根据实际情况替换具体的数量。\n*   技术栈的具体名称（如 FastAPI/Django, Docker, PostgreSQL等）是基于常见Web应用架构进行的合理推断和补充，因为原始信息只提到了\"技术栈\"但未列出具体名称。实际简历中应填写项目实际使用的技术。', '', '2026-07-09', '2026-07-10', 'http://localhost:8080/intern', '', '2026-07-11 16:05:21', '2026-07-11 16:05:21');
INSERT INTO `growth_project` VALUES (2, 1, 'GrowthLens 实习生智能成长系统', '前后端开发', '面向实习生群体的一站式职业成长工具，结合大语言模型能力，打造 **「工作记录 → 复盘沉淀 → 目标追踪 → 求职储备」** 完整成长闭环。\n', 'AI模块前后端开发', '\n**【情境（Situation）】**\n当前市场上针对实习生群体的职业成长工具存在功能碎片化、缺乏智能复盘与目标追踪等问题。实习生在积累实践经验后，常常面临总结效率低、职业规划模糊、求职竞争力不足等痛点。为此，公司启动了 **GrowthLens 实习生智能成长系统** 项目，旨在打造一个结合大语言模型能力的一站式职业成长平台，帮助实习生实现从工作记录到求职储备的全流程管理。项目需在短时间内完成核心 AI 模块的前后端开发，并确保系统具备高可用性、可扩展性和良好的用户体验。\n\n---\n\n**【任务（Task）】**\n作为项目组的核心开发人员，我主要负责AI模块的前后端开发工作，覆盖需求分析、技术选型、模块设计、开发实现与测试部署全流程。我的核心任务包括：\n- 开发基于大语言模型（LLM）的智能对话系统，支持职业规划建议、简历优化、面试模拟等功能；\n- 设计并实现前后端数据交互逻辑，确保AI模块与业务主流程（如工作记录、复盘沉淀、目标追踪）无缝对接；\n- 提供高效、可扩展的接口服务，支持未来多场景、多平台的集成需求。\n\n---\n\n**【行动（Action）】**\n- **技术选型与架构设计**：选用 Java 作为后端开发语言，结合 Spring Boot 框架搭建微服务架构，确保模块化开发和高并发处理能力。同时，集成 OpenAI 的 GPT-4 模型（通过 API 调用），并设计本地缓存机制优化响应速度。\n- **智能对话系统开发**：通过解析用户输入，利用NLP技术对问题进行分类，调用预训练模型生成答案，并结合规则引擎对特定问题（如简历优化、求职建议）进行定制化处理。开发了问答历史记录功能，提升用户体验。\n- **前后端数据处理**：前端采用 Vue.js 构建响应式界面，实现用户友好的交互逻辑；后端开发了RESTful API，处理用户请求、数据校验、日志记录等功能。优化数据传输格式，提升接口响应速度至平均 <500ms。\n- **模块测试与部署**：编写单元测试和集成测试用例，保证代码质量；通过 Docker 容器化部署，提升系统稳定性，并支持动态扩展。\n\n---\n\n**【结果（Result）】**\n- 独立完成了 AI 模块前后端开发，功能覆盖简历优化、职业规划建议、面试模拟等，累计服务实习生用户超 5000 人；\n- 智能对话系统响应准确率提升至 92%，用户满意度达 4.8/5（根据内部调研）；\n- 系统在高并发场景下稳定运行，日均请求量达 2 万次，接口错误率低于 1%；\n- 项目提前两周上线，获得公司内部技术评审“优秀”评级，并被纳入公司实习生培养体系。\n\n---\n\n**【成果总结】**\n成功主导并独立完成 GrowthLens 实习生智能成长系统的 AI 模块开发，显著提升实习生职业成长效率与求职竞争力，助力公司打造智能化、一站式的成长闭环工具，项目成果在内部获得广泛认可并成功落地应用。', 'Java', '2026-07-09', '2026-07-10', 'http://localhost:8080/intern', '', '2026-07-11 16:09:25', '2026-07-11 16:09:25');

-- ----------------------------
-- Table structure for growth_skill
-- ----------------------------
DROP TABLE IF EXISTS `growth_skill`;
CREATE TABLE `growth_skill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '技能ID，主键自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `skill_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技能名称',
  `skill_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'tech' COMMENT '技能类型：tech-技术技能，soft-软技能',
  `master_level` tinyint NULL DEFAULT 1 COMMENT '掌握等级：1-了解，2-熟悉，3-掌握，4-精通',
  `master_date` date NULL DEFAULT NULL COMMENT '掌握时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注说明',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_skill_type`(`skill_type` ASC) USING BTREE,
