-- ----------------------------
-- Table structure for interview_question
-- ----------------------------
DROP TABLE IF EXISTS `interview_question`;
CREATE TABLE `interview_question`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '题目ID，主键自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `category_id` bigint NULL DEFAULT NULL COMMENT '所属分类ID',
  `question_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目标题',
  `question_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '题目详细内容',
  `my_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '我的答案',
  `reference_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '参考答案（AI生成）',
  `review_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '复盘总结/优化思路',
  `difficulty_level` tinyint NULL DEFAULT 2 COMMENT '难度：1-简单，2-中等，3-困难',
  `master_level` tinyint NULL DEFAULT 1 COMMENT '掌握程度：1-不熟，2-熟练，3-精通',
  `source_company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源公司',
  `source_post` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源岗位',
  `is_collected` tinyint NULL DEFAULT 0 COMMENT '是否收藏：0-否，1-是',
  `is_wrong` tinyint NULL DEFAULT 0 COMMENT '是否错题：0-否，1-是',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_category_id`(`category_id` ASC) USING BTREE,
  INDEX `idx_difficulty`(`difficulty_level` ASC) USING BTREE,
  INDEX `idx_master_level`(`master_level` ASC) USING BTREE,
  INDEX `idx_is_collected`(`is_collected` ASC) USING BTREE,
  INDEX `idx_is_wrong`(`is_wrong` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '面试题库表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of interview_question
-- ----------------------------
INSERT INTO `interview_question` VALUES (1, 1, 1, '以下哪个不属于腾讯游戏？', '以下哪个不属于腾讯游戏？ A.《王者荣耀》 B.《和平精英》 C.《原神》 D.《穿越火线》', 'C', '\n\n正确答案是：**C. 《原神》**\n\n以下是详细解析：\n\n1.  **A. 《王者荣耀》**\n    *   **归属：** 属于腾讯游戏。\n    *   **开发商：** 腾讯天美工作室群（TiMi Studio Group）。\n    *   **说明：** 这是腾讯游戏最著名的 MOBA（多人在线战术竞技）手游之一，完全由腾讯内部开发和运营。\n\n2.  **B. 《和平精英》**\n    *   **归属：** 属于腾讯游戏。\n    *   **开发商：** 腾讯游戏上海（Tencent Games Shanghai）。\n    *   **说明：** 这是一款知名的战术竞技类射击手游，由腾讯直接开发出版。\n\n3.  **C. 《原神》**\n    *   **归属：** **不属于**腾讯游戏（属于米哈游）。\n    *   **开发商：** 米哈游（miHoYo），现官方名称为 HoYoverse。\n    *   **说明：** 虽然腾讯曾在 2019 年战略入股并收购了米哈游 49% 的股份，但《原神》的出品方、运营方及品牌归属依然明确为米哈游/ HoYoverse，而非腾讯游戏官方体系下的核心产品。在行业分类和公众认知中，它被归类为米哈游游戏。\n\n4.  **D. 《穿越火线》**\n    *   **归属：** 属于腾讯游戏。\n    *   **开发商：** 腾讯在线娱乐（Tencent Online Entertainment）。\n    *   **说明：** 这是一款经典的 FPS（第一人称射击）游戏，腾讯拥有其知识产权并负责运营。\n\n**总结：**\n选项 A、B、D 均为腾讯全资或核心内部开发运营的游戏，而选项 C《原神》由米哈游开发，因此 **C** 是正确答案。', '下次还填非常简单', 1, 3, '腾讯', 'java工程师', 0, 0, '2026-07-08 08:48:24', '2026-07-08 08:51:07');

-- ----------------------------
-- Table structure for review_record
-- ----------------------------
DROP TABLE IF EXISTS `review_record`;
CREATE TABLE `review_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '复盘ID，主键自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `review_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '类型：daily-日度/weekly-周度',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `original_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '原始日报内容',
  `highlight` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '复盘亮点',
  `shortage` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '存在不足',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '改进建议',
  `full_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '完整复盘内容',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-失败，1-成功',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_review_type`(`review_type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `start_date` ASC, `end_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '复盘记录表' ROW_FORMAT = Dynamic;

